# ==============================================================================# 039_WORKFLOW_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS workflows(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    workflow_name TEXT,    description TEXT,    total_tasks INTEGER,    completed_tasks INTEGER,    progress REAL,    status TEXT)""")conn.commit()cur.execute("""SELECT COUNT(*)FROM task_queue""")total = cur.fetchone()[0]cur.execute("""SELECT COUNT(*)FROM task_queueWHERE status='COMPLETED'""")completed = cur.fetchone()[0]progress = 0if total > 0:    progress = round((completed / total) * 100, 2)workflow_name = "MISSION_CONTROL_STARTUP"cur.execute("""SELECT idFROM workflowsWHERE workflow_name=?""",(workflow_name,))exists = cur.fetchone()if exists is None:    cur.execute("""    INSERT INTO workflows(        created_at,        workflow_name,        description,        total_tasks,        completed_tasks,        progress,        status    )    VALUES(?,?,?,?,?,?,?)    """,(        datetime.now().isoformat(),        workflow_name,        "Fluxo principal de inicializaÃ§Ã£o do Mission Control",        total,        completed,        progress,        "COMPLETED" if progress == 100 else "RUNNING"    ))else:    cur.execute("""    UPDATE workflows    SET        total_tasks=?,        completed_tasks=?,        progress=?,        status=?    WHERE workflow_name=?    """,(        total,        completed,        progress,        "COMPLETED" if progress == 100 else "RUNNING",        workflow_name    ))conn.commit()cur.execute("""SELECTworkflow_name,total_tasks,completed_tasks,progress,statusFROM workflowsORDER BY id DESCLIMIT 1""")row = cur.fetchone()print("=" * 80)print("WORKFLOW ENGINE")print("=" * 80)print(f"Workflow   : {row['workflow_name']}")print(f"Tarefas    : {row['completed_tasks']} / {row['total_tasks']}")print(f"Progresso  : {row['progress']} %")print(f"Status     : {row['status']}")print("=" * 80)conn.close()

